{"files": {"src/producer.py": "import sys
import json

UNITS = {"g": 1000, "kg": 1000000, "mg": 1}

def to_base(v, u, units):
    return v * units[u]

def main():
    req = sys.argv[1] if len(sys.argv) > 1 else None
    resp = sys.argv[2] if len(sys.argv) > 2 else None
    with open(req, 'r') as f:
        data = json.load(f)
    units = data.get('units', data.get('Units', UNITS))
    if not isinstance(units, dict) or not units:
        units = UNITS
    readings = data.get('readings', data.get('Readings', []))
    want = data.get('want', data.get('Want'))
    want_size = units[want]
    values = []
    for r in readings:
        if isinstance(r, dict):
            v = r.get('v', r.get('V', r.get('value', r.get('Value'))))
            u = r.get('u', r.get('U', r.get('unit', r.get('Unit'))))
        else:
            continue
        base = to_base(v, u, units)
        values.append(round(base / want_size, 2))
    with open(resp, 'w') as f:
        json.dump({"values": values}, f)

if __name__ == '__main__':
    main()
"}, "notes": "Fixed to_base to multiply by unit size and added main to convert via base unit then divide by wanted size with round to 2 decimals."}
